    WHERE recipe_version_id = (SELECT rv.id FROM public.recipe_versions rv
      JOIN public.product_categories pc ON pc.id = rv.category_id
      LEFT JOIN public.color_palette cp ON cp.id = rv.color_id
      WHERE rv.organization_id = org AND pc.category_id_ref = 'posts_and_bicons' AND rv.version_number = 1
        AND rv.status = 'active' AND rv.variant_label = 'Standard') AND material_id = (SELECT id FROM public.materials WHERE organization_id = org AND material_id_ref = 'chipping') AND unit_id IS DISTINCT FROM (SELECT id FROM public.units WHERE organization_id = org AND symbol = 'bucket');
  SELECT count(*) INTO n FROM public.recipe_items WHERE recipe_version_id = (SELECT rv.id FROM public.recipe_versions rv
      JOIN public.product_categories pc ON pc.id = rv.category_id
      LEFT JOIN public.color_palette cp ON cp.id = rv.color_id
      WHERE rv.organization_id = org AND pc.category_id_ref = 'posts_and_bicons' AND rv.version_number = 1
        AND rv.status = 'active' AND rv.variant_label = 'Standard') AND material_id = (SELECT id FROM public.materials WHERE organization_id = org AND material_id_ref = 'chipping');
  IF n <> 1 THEN RAISE EXCEPTION 'G: chipping line in posts_and_bicons/Standard: expected 1, got %', n; END IF;

